"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["91091"],{69338(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.certame_publicado.envelope_inesperado","status":422,"titulo":"A configura\xe7\xe3o congelada n\xe3o tem a forma que a proje\xe7\xe3o p\xfablica espera"},"descricao":{"codigo":"uniplus.selecao.certame_publicado.envelope_inesperado","requisitos":[],"oQueAconteceu":["A consulta p\xfablica do certame (`GET /api/selecao/certames/{id}`, an\xf4nima, pelo identificador do processo ou pelo identificador leg\xedvel) devolve os dados da vers\xe3o publicada. Antes de responder, a API confere se os dados guardados podem ser lidos, cont\xeam os blocos obrigat\xf3rios e seguem o formato conhecido pela vers\xe3o atual.","Aqui a confer\xeancia falhou. O documento guardado n\xe3o p\xf4de ser lido, faltam\\nblocos que o formato atual exige ou ele foi gravado num formato de proje\xe7\xe3o\\nanterior. A API recusa a leitura com **422** em vez de responder s\xf3 com parte do\\ncertame, porque uma resposta incompleta, com o selo da vers\xe3o completa, ficaria\\nguardada em cache como se estivesse inteira. A mensagem indica a parte que n\xe3o\\np\xf4de ser lida, sem trazer o conte\xfado do documento.","A publica\xe7\xe3o e a retifica\xe7\xe3o em ato \xfanico tamb\xe9m montam essa proje\xe7\xe3o, a\\npartir da vers\xe3o que acabaram de congelar, e propagam a mesma recusa se a\\nmontagem falhar. Essa montagem l\xea o que o pr\xf3prio sistema acabou de gravar, e\\nnenhum dado do pedido a faz falhar: por isso nenhuma dessas opera\xe7\xf5es consta no\\ncabe\xe7alho, e a consulta p\xfablica \xe9 o \xfanico\\nponto em que a recusa chega a quem consome a API.","Esta recusa \xe9 diferente do n\xe3o encontrado. Processo inexistente, em rascunho,\\nsem vers\xe3o vigente ou cujo ato ainda n\xe3o foi registrado respondem **404**, com a\\nmesma resposta para todos os casos. J\xe1 a listagem p\xfablica de certames n\xe3o\\ndevolve este erro: ela deixa de fora o certame cujo documento n\xe3o p\xf4de ser\\nlido, e os demais continuam na lista."],"comoResolver":["Quem consulta n\xe3o tem o que corrigir no pedido, e repetir a consulta n\xe3o muda o\\nresultado enquanto o documento guardado continuar ileg\xedvel. Como o identificador\\ninformado j\xe1 localizou a divulga\xe7\xe3o, a causa est\xe1 no documento guardado nela\\n(ileg\xedvel, incompleto ou de formato anterior), e n\xe3o no pedido. A causa \xe9\\ninvestigada pela equipe t\xe9cnica do Uni+."],"ondeAparece":["Consulta p\xfablica do certame publicado"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Certame publicado"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);